-- Visitor-submitted testimonials.
--
-- These were editorial content in `src/content/testimonials.ts` until the
-- practice asked to collect them through the site. Anything a visitor writes
-- has to be read before it is published — an unmoderated comment box on a
-- therapist's homepage is an invitation — so a submission lands as `pending`
-- and appears nowhere until it is approved.
--
-- The ten already published are seeded below, approved, so nothing that is
-- live today disappears when this runs.

create table if not exists testimonial (
  id           integer     primary key generated always as identity,
  -- First name only, by convention; the form asks for nothing more.
  name         text        not null,
  -- ISO 3166-1 alpha-2, resolved to a Persian name and a flag at render.
  country_code text,
  quote        text        not null,
  status       text        not null default 'pending'
               check (status in ('pending', 'approved', 'rejected')),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- The admin list is "what is waiting on me, newest first".
create index if not exists testimonial_status_idx
  on testimonial (status, created_at desc);

insert into testimonial (name, country_code, quote, status) values
  ('سارا', 'IR', 'تجربه خیلی خوبی از جلسات داشتم. برخورد دکتر هم حرفه‌ای بود و هم صمیمانه، به شکلی که از همان جلسه اول احساس راحتی کردم. چیزی که برای من خیلی ارزشمند بود این بود که فقط درباره مشکلات صحبت نمی‌کردیم و در پایان جلسات معمولاً با دید روشن‌تر و راهکارهای عملی‌تری از جلسه بیرون می‌آمدم.', 'approved'),
  ('شیرین', 'DE', 'از مراجعه به ایشون خیلی راضی هستم. فضای جلسات آرام و محترمانه است و هیچ‌وقت احساس قضاوت یا فشار نداشتم. کمک کردند بعضی از موضوعاتی که مدت‌ها برای خودم پیچیده بود را از زاویه متفاوتی ببینم و بهتر بتونم باهاشون برخورد کنم.', 'approved'),
  ('محمد', 'IR', 'دکتر بسیار حرفه‌ای و خوش‌برخورد هستند و جلسات نظم و ساختار خوبی دارد. برای من مهم بود که روند مشاوره فقط به صحبت کردن محدود نشود و احساس کنم در طول زمان واقعاً دارم روی مسائل مختلف کار می‌کنم. بعد از چند جلسه تغییرات مثبتی در نوع نگاه و تصمیم‌گیری خودم احساس کردم.', 'approved'),
  ('مینا', 'SE', 'چیزی که بیشتر از همه دوست داشتم، نوع ارتباطی بود که در جلسات شکل گرفت. خیلی راحت می‌شد درباره موضوعاتی که شاید معمولاً صحبت کردن در موردشان سخت باشد حرف زد. در کنار این حس راحتی، راهنمایی‌ها هم کاملاً حرفه‌ای و منطقی بود و باعث شد بعضی مسائل را خیلی بهتر مدیریت کنم.', 'approved'),
  ('نگار', 'IR', 'تجربه من واقعاً مثبت بود. دکتر با آرامش و حوصله موضوعات را بررسی می‌کنند و در عین حال کمک می‌کنند خود آدم هم به نتیجه و شناخت بهتری برسد. احساس نمی‌کردم صرفاً یک سری توصیه آماده دریافت می‌کنم؛ راهکارها متناسب با شرایط و شخصیت خودم بود و همین موضوع برایم خیلی مفید بود.', 'approved'),
  ('بابک', 'CA', 'از کیفیت جلسات و برخورد حرفه‌ای ایشون خیلی راضی بودم. محیط جلسه حس امنیت و آرامش خوبی داشت و روند مشاوره هم هدفمند بود. نکته‌ای که برای من جالب بود این بود که گاهی با چند سؤال یا توضیح ساده کمک می‌کردند متوجه ریشه بعضی رفتارها و احساساتی بشم که قبلاً اصلاً بهشون توجه نکرده بودم.', 'approved'),
  ('امیر', 'IR', 'دکتر بسیار محترم، مسئولیت‌پذیر و حرفه‌ای هستند. جلسات به من کمک کرد هم خودم را بهتر بشناسم و هم در ارتباط با اطرافیانم تصمیم‌های بهتری بگیرم. به نظرم یکی از نقاط قوت ایشون اینه که مسائل رو پیچیده‌تر از چیزی که هست نمی‌کنند و توضیحاتشون واضح و قابل استفاده در زندگی روزمره است.', 'approved'),
  ('رویا', 'TR', 'قبل از شروع جلسات کمی تردید داشتم که مشاوره چقدر می‌تواند برایم مفید باشد، اما تجربه خیلی بهتری از چیزی بود که انتظار داشتم. به مرور احساس کردم نسبت به بعضی نگرانی‌ها و چالش‌ها کنترل بیشتری دارم و می‌توانم با آرامش بیشتری با آن‌ها روبه‌رو شوم. از زمانی که برای این جلسات گذاشتم کاملاً راضی هستم.', 'approved'),
  ('سهیل', 'AE', 'تجربه بسیار خوبی داشتم و با خیال راحت ایشون رو پیشنهاد می‌کنم. علاوه بر برخورد گرم و محترمانه، چیزی که برای من مهم بود این بود که در جلسات حس می‌کردم یک مسیر مشخص وجود دارد و هر جلسه ادامه و تکمیل جلسه قبل است. این موضوع باعث شد بعد از مدتی واقعاً متوجه پیشرفت خودم بشم.', 'approved'),
  ('کیوان', 'AU', 'از خدمات و جلسات مشاوره بسیار راضی بودم. دکتر فضای بسیار خوبی ایجاد می‌کنند که آدم بتواند بدون استرس درباره مسائل مختلف صحبت کند، اما در عین حال جلسات کاملاً حرفه‌ای و هدفمند باقی می‌ماند. راهنمایی‌هایی که دریافت کردم باعث شد در بعضی موقعیت‌ها واکنش‌های متفاوت و بهتری داشته باشم و در مجموع تجربه ارزشمندی برای من بود.', 'approved');
